"""Applies Landed's Android settings to the project generated by `flutter create`.

Run from the flutter/ directory after `flutter create`.
"""
from pathlib import Path

manifest = Path("android/app/src/main/AndroidManifest.xml")
m = manifest.read_text()
m = m.replace('android:label="landed"', 'android:label="Landed"')
if "android:allowBackup" not in m:
    m = m.replace(
        "<application",
        '<application\n        android:allowBackup="false"\n        android:fullBackupContent="false"\n'
        '        android:dataExtractionRules="@xml/data_extraction_rules"',
        1,
    )
for perm in ["android.permission.INTERNET", "android.permission.ACCESS_COARSE_LOCATION"]:
    if perm not in m:
        m = m.replace("<application", f'<uses-permission android:name="{perm}" />\n    <application', 1)
manifest.write_text(m)

gradle = Path("android/app/build.gradle.kts")
g = gradle.read_text()
if 'create("release")' not in g:
    signing = '''    signingConfigs {
        create("release") {
            val ks = System.getenv("LANDED_KEYSTORE")
            if (ks != null && ks.isNotEmpty()) {
                storeFile = file(ks)
                storePassword = System.getenv("LANDED_KEYSTORE_PASSWORD")
                keyAlias = System.getenv("LANDED_KEY_ALIAS") ?: "landed"
                keyPassword = System.getenv("LANDED_KEYSTORE_PASSWORD")
            }
        }
    }

    buildTypes {'''
    g = g.replace("    buildTypes {", signing, 1)
    g = g.replace(
        'signingConfig = signingConfigs.getByName("debug")',
        'signingConfig = if (System.getenv("LANDED_KEYSTORE").isNullOrEmpty()) '
        'signingConfigs.getByName("debug") else signingConfigs.getByName("release")',
        1,
    )
gradle.write_text(g)
print(manifest.read_text())
print(g)
